/**
 * Seed the SQLite database with the venue, its two courts, and 30 days of
 * hourly slot availability — generated by the same mock engine the UI uses
 * (`src/data/slots.ts`), so UI and DB stay consistent until the AYO
 * integration lands.
 *
 * Idempotent: re-running upserts by primary key and refreshes slot statuses.
 *
 * Usage: npm run db:seed
 */
import { eq, ne, sql } from "drizzle-orm";
import { db, schema } from "../src/db/index";
import { courts as courtData } from "../src/data/courts";
import { blogPosts as blogData } from "../src/data/blog-posts";
import { events as eventData } from "../src/data/events";
import { galleryPhotos as galleryData } from "../src/data/gallery";
import { faqItems } from "../src/data/faq";
import { facilities as facilityData } from "../src/data/facilities";
import { testimonials as testimonialData } from "../src/data/testimonials";
import {
  FREE_TRIAL_REGISTRATION_URL,
  programs as programData,
} from "../src/data/programs";
import { FIRST_HOUR, LAST_HOUR } from "../src/data/pricing";
import { getSlotPrice } from "../src/data/pricing";
import { archivedPromos, promos as runningPromos } from "../src/data/promos";
import { site } from "../src/data/site";
import { parseIDR } from "../src/lib/format";

const VENUE_ID = "get-padel-jakarta";

function localImage(courtId: string): string {
  return `/images/${courtId}.jpg`;
}

async function seedVenue() {
  await db
    .insert(schema.venues)
    .values({
      id: VENUE_ID,
      name: site.name,
      tagline: site.tagline,
      addressStreet: site.address.street,
      addressDistrict: site.address.district,
      addressCity: site.address.city,
      plusCode: site.address.plusCode,
      latitude: site.address.coordinates.lat,
      longitude: site.address.coordinates.lng,
      courtOpenHour: 6,
      courtCloseHour: 22,
      cafeOpenHour: 7,
      cafeCloseHour: 22,
      sessionMinutes: 60,
      ratingGoogle: site.ratings.google.score,
      ratingGoogleCount: site.ratings.google.count,
      ratingAyo: site.ratings.ayo.score,
      ratingAyoCount: site.ratings.ayo.count,
      ratingCleanliness: site.ratings.sub.cleanliness,
      ratingCourtCondition: site.ratings.sub.court,
      ratingCommunication: site.ratings.sub.communication,
      whatsapp: site.contact.whatsapp,
      emailEvent: site.contact.emailEvent,
      emailCommercial: site.contact.emailCommercial,
      instagramUrl: site.links.instagram,
      tiktokUrl: site.links.tiktok,
      cafeInstagramUrl: site.links.cafeInstagram,
      bookingUrl: site.links.ayo,
      mapsUrl: site.links.maps,
      linktreeUrl: site.links.linktree,
      updatedAt: new Date(),
    })
    .onConflictDoUpdate({
      target: schema.venues.id,
      set: {
        name: site.name,
        tagline: site.tagline,
        addressStreet: site.address.street,
        addressDistrict: site.address.district,
        addressCity: site.address.city,
        plusCode: site.address.plusCode,
        latitude: site.address.coordinates.lat,
        longitude: site.address.coordinates.lng,
        ratingGoogle: site.ratings.google.score,
        ratingGoogleCount: site.ratings.google.count,
        ratingAyo: site.ratings.ayo.score,
        ratingAyoCount: site.ratings.ayo.count,
        ratingCleanliness: site.ratings.sub.cleanliness,
        ratingCourtCondition: site.ratings.sub.court,
        ratingCommunication: site.ratings.sub.communication,
        whatsapp: site.contact.whatsapp,
        updatedAt: new Date(),
      },
    });
  console.log(`✓ venue ${VENUE_ID}`);
}

async function seedCourts() {
  for (const [index, court] of courtData.entries()) {
    const values = {
      id: court.id,
      venueId: VENUE_ID,
      name: court.name,
      indoor: court.indoor,
      surface: court.surface,
      sessionMinutes: court.sessionMinutes,
      descriptionEn: court.description,
      imageUrl: localImage(court.id),
      sortOrder: index + 1,
    };
    await db
      .insert(schema.courts)
      .values(values)
      .onConflictDoUpdate({
        target: schema.courts.id,
        set: {
          name: values.name,
          surface: values.surface,
          sessionMinutes: values.sessionMinutes,
          descriptionEn: values.descriptionEn,
          imageUrl: values.imageUrl,
          sortOrder: values.sortOrder,
        },
      });
  }
  console.log(`✓ courts ${courtData.map((court) => court.id).join(", ")}`);
}

async function seedFacilities() {
  for (const [index, facility] of facilityData.entries()) {
    const values = {
      id: facility.id,
      venueId: VENUE_ID,
      titleId: facility.title.id,
      titleEn: facility.title.en,
      detailId: facility.detail?.id ?? null,
      detailEn: facility.detail?.en ?? null,
      icon: facility.icon,
      official: facility.official,
      sortOrder: index + 1,
    };
    await db
      .insert(schema.facilities)
      .values(values)
      .onConflictDoUpdate({
        target: schema.facilities.id,
        set: {
          titleId: values.titleId,
          titleEn: values.titleEn,
          detailId: values.detailId,
          detailEn: values.detailEn,
          icon: values.icon,
          official: values.official,
          sortOrder: values.sortOrder,
        },
      });
  }
  const officialCount = facilityData.filter((facility) => facility.official).length;
  console.log(
    `✓ facilities ${facilityData.length} rows (${officialCount} official + ${facilityData.length - officialCount} extras)`
  );
}

const PROGRAM_KINDS: Record<string, "private" | "multi_session" | "junior" | "free_trial"> = {
  "private-coaching": "private",
  "multi-session-coaching": "multi_session",
  "junior-class": "junior",
  "free-trial": "free_trial",
};

async function seedPrograms() {
  for (const [index, program] of programData.entries()) {
    const kind = PROGRAM_KINDS[program.id];
    if (!kind) continue;
    const values = {
      id: program.id,
      venueId: VENUE_ID,
      kind,
      titleId: program.title.id,
      titleEn: program.title.en,
      descriptionId: program.description.id,
      descriptionEn: program.description.en,
      highlights: JSON.stringify(program.highlights),
      priceNoteId: program.priceNote?.id ?? null,
      priceNoteEn: program.priceNote?.en ?? null,
      ctaKind:
        program.cta === "form"
          ? ("form" as const)
          : program.cta === "ayo"
            ? ("ayo" as const)
            : ("whatsapp" as const),
      registrationUrl:
        program.cta === "form" ? FREE_TRIAL_REGISTRATION_URL : null,
      isActive: true,
      sortOrder: index + 1,
      updatedAt: new Date(),
    };
    await db
      .insert(schema.coachingPrograms)
      .values(values)
      .onConflictDoUpdate({
        target: schema.coachingPrograms.id,
        set: {
          kind: values.kind,
          titleId: values.titleId,
          titleEn: values.titleEn,
          descriptionId: values.descriptionId,
          descriptionEn: values.descriptionEn,
          highlights: values.highlights,
          priceNoteId: values.priceNoteId,
          priceNoteEn: values.priceNoteEn,
          ctaKind: values.ctaKind,
          registrationUrl: values.registrationUrl,
          isActive: values.isActive,
          sortOrder: values.sortOrder,
          updatedAt: values.updatedAt,
        },
      });

    for (const [tierIndex, tier] of (program.priceRows ?? []).entries()) {
      const tierValues = {
        id: `${program.id}:${tierIndex + 1}`,
        programId: program.id,
        labelId: tier.label.id,
        labelEn: tier.label.en,
        priceIdr: parseIDR(tier.value),
        sortOrder: tierIndex + 1,
      };
      await db
        .insert(schema.coachingProgramTiers)
        .values(tierValues)
        .onConflictDoUpdate({
          target: schema.coachingProgramTiers.id,
          set: {
            labelId: tierValues.labelId,
            labelEn: tierValues.labelEn,
            priceIdr: tierValues.priceIdr,
            sortOrder: tierValues.sortOrder,
          },
        });
    }
  }
  const tierCount = programData.reduce(
    (total, program) => total + (program.priceRows?.length ?? 0),
    0
  );
  console.log(
    `✓ coaching_programs ${programData.length} rows · tiers ${tierCount} rows`
  );
}

