async function seedGallery() {
  for (const [index, photo] of galleryData.entries()) {
    const values = {
      id: photo.id,
      venueId: VENUE_ID,
      src: photo.src,
      altId: photo.alt.id,
      altEn: photo.alt.en,
      isActive: true,
      sortOrder: index + 1,
      updatedAt: new Date(),
    };
    await db
      .insert(schema.galleryPhotos)
      .values(values)
      .onConflictDoUpdate({
        target: schema.galleryPhotos.id,
        set: {
          src: values.src,
          altId: values.altId,
          altEn: values.altEn,
          isActive: values.isActive,
          sortOrder: values.sortOrder,
          updatedAt: values.updatedAt,
        },
      });
  }
  // Remove photos that are no longer part of the seeded set (keeps the
  // gallery duplicate-free after content changes).
  const keep = new Set(galleryData.map((photo) => photo.id));
  const existing = await db
    .select({ id: schema.galleryPhotos.id })
    .from(schema.galleryPhotos);
  for (const row of existing) {
    if (!keep.has(row.id)) {
      await db
        .delete(schema.galleryPhotos)
        .where(eq(schema.galleryPhotos.id, row.id));
    }
  }
  console.log(`✓ gallery_photos ${galleryData.length} rows`);
}

