/**
 * The schedule is NEVER seeded from fabricated data. Legacy mock rows (from
 * the pre-AYO prototype) are removed so only official AYO syncs remain.
 */
async function purgeMockSlots() {
  const result = await db
    .delete(schema.scheduleSlots)
    .where(ne(schema.scheduleSlots.source, "ayo"));
  console.log("✓ schedule_slots pruned to official AYO rows");
  return result;
}

/** Representative dates per day type (Monday & Saturday). */
const SAMPLE_DATE: Record<"weekday" | "weekend", string> = {
  weekday: "2026-09-21",
  weekend: "2026-09-26",
};

async function seedPricing() {
  const rows: (typeof schema.pricingRules.$inferInsert)[] = [];
  for (const dayType of ["weekday", "weekend"] as const) {
    for (let hour = FIRST_HOUR; hour <= LAST_HOUR; hour++) {
      const { price, strike } = getSlotPrice(SAMPLE_DATE[dayType], hour);
      rows.push({
        id: `${dayType}:${hour}`,
        venueId: VENUE_ID,
        dayType,
        hour,
        price,
        strikePrice: strike,
        isPeak: dayType === "weekend" ? hour >= 7 : hour >= 18,
      });
    }
  }

  await db
    .insert(schema.pricingRules)
    .values(rows)
    .onConflictDoUpdate({
      target: schema.pricingRules.id,
      set: {
        price: sql`excluded.price`,
        strikePrice: sql`excluded.strike_price`,
        isPeak: sql`excluded.is_peak`,
      },
    });
  console.log(`✓ pricing_rules ${rows.length} rows (weekday + weekend × 16 hours)`);
}

async function seedPromos() {
  const all = [...runningPromos, ...archivedPromos];
  const rows: (typeof schema.promos.$inferInsert)[] = all.map(
    (promo, index) => ({
      id: promo.id,
      venueId: VENUE_ID,
      titleId: promo.title.id,
      titleEn: promo.title.en,
      code: null,
      periodId: promo.period.id,
      periodEn: promo.period.en,
      detailId: promo.detail.id,
      detailEn: promo.detail.en,
      source: promo.source ?? null,
      linkUrl: promo.link ?? null,
      reference: promo.reference ?? null,
      posterUrl: promo.poster ?? null,
      startsOn: promo.startsOn ?? null,
      endsOn: promo.endsOn ?? null,
      isActive: !promo.archived,
      sortOrder: index,
      updatedAt: new Date(),
    })
  );

  for (const row of rows) {
    await db
      .insert(schema.promos)
      .values(row)
      .onConflictDoUpdate({
        target: schema.promos.id,
        set: {
          titleId: sql`excluded.title_id`,
          titleEn: sql`excluded.title_en`,
          periodId: sql`excluded.period_id`,
          periodEn: sql`excluded.period_en`,
          detailId: sql`excluded.detail_id`,
          detailEn: sql`excluded.detail_en`,
          source: sql`excluded.source`,
          linkUrl: sql`excluded.link_url`,
          reference: sql`excluded.reference`,
          posterUrl: sql`excluded.poster_url`,
          startsOn: sql`excluded.starts_on`,
          endsOn: sql`excluded.ends_on`,
          isActive: sql`excluded.is_active`,
          sortOrder: sql`excluded.sort_order`,
          updatedAt: sql`excluded.updated_at`,
        },
      });
  }
  console.log(
    `✓ promos ${rows.length} rows (${runningPromos.length} running + ${archivedPromos.length} archived)`
  );
}

async function main() {
  await seedVenue();
  await seedCourts();
  await seedFacilities();
  await seedPrograms();
  await seedEvents();
  await seedFaqs();
  await seedTestimonials();
  await seedGallery();
  await seedBlogPosts();
  await purgeMockSlots();
  await seedPricing();
  await seedPromos();
  console.log("Seed complete.");
}

main().catch((error) => {
  console.error("Seed failed:", error);
  process.exit(1);
});
